using System;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using System.Web.Script.Serialization;
namespace SplifyWin {
 public static partial class VkTurnOptions {
  static string Scalar(Dictionary<string,object> d,string key,string fallback=""){object value;if(!d.TryGetValue(key,out value)||value==null)return fallback;if(value is bool)return (bool)value?"true":"false";if(value is string||value is ValueType)return Convert.ToString(value,System.Globalization.CultureInfo.InvariantCulture);var sequence=value as IEnumerable;if(sequence!=null)return String.Join("\n",sequence.Cast<object>().Select(v=>Convert.ToString(v)));throw new FormatException("Некорректное поле TURN: "+key);}
  public static List<ServerNode> ReadProfiles(string input){
   if(input.Length>1048576)throw new FormatException("Профиль TURN слишком велик.");var json=new JavaScriptSerializer{MaxJsonLength=1048576};object root=json.DeserializeObject(input);var single=root as Dictionary<string,object>;var profiles=single!=null?new[]{single}:((IEnumerable)root).Cast<object>().Select(p=>p as Dictionary<string,object>).ToArray();if(profiles.Length==0||profiles.Length>2048||profiles.Any(p=>p==null))throw new FormatException("Нужны профили подключений TURN.");var result=new List<ServerNode>();
   foreach(var d in profiles){string kind=Scalar(d,"type");if(!new[]{"csqtt","wdtt","qwdtt"}.Contains(kind))throw new FormatException("JSON-импорт поддерживает здесь только профили CSQTT, WDTT и QWDTT.");
    string[] metadata={"type","name","outbound_tag","probe_only","csqtt_generation","csqtt_implementation","workers","workers_override","link_workers","hash_source","vk_call_count","captcha_mode","mode","rt_masque","turn_sni","server","server_port","password","hashes","wg_port","local_port","vk_anon_path","turn_tcp"};string[] options={"device_id","obfs","fingerprint","turn_transport","vk_auth_mode","go_dns","raw_port","client_ids","allow_hash_redistribution","generation","salt","vk_token","vk_hash_mode","extra_streams","custom_turn_ips","custom_vk_client_id","custom_vk_client_secret","vkcalls_preflight","turn_stream_first"};if(d.Keys.Any(k=>!metadata.Contains(k)&&!options.Contains(k)))throw new FormatException("Неизвестное поле профиля TURN. Импорт отменён без потери параметров.");
    var p=new VkTurnServerPreferences();foreach(string k in options)if(d.ContainsKey(k))p.Options[k]=Scalar(d,k);if(d.ContainsKey("csqtt_implementation"))p.Options["implementation"]=Scalar(d,"csqtt_implementation");if(d.ContainsKey("vk_anon_path"))p.Options["vk_auth_mode"]=Scalar(d,"vk_anon_path");if(d.ContainsKey("turn_tcp")){string v=Scalar(d,"turn_tcp");if(!new[]{"true","false","1","0"}.Contains(v))throw new FormatException("Некорректный TURN TCP.");p.Options["turn_transport"]=v=="true"||v=="1"?"tcp":"udp";}
    p.CaptchaMode=Scalar(d,"captcha_mode","auto");if(p.CaptchaMode=="wv")p.CaptchaMode="manual";p.Masque=Scalar(d,"rt_masque")=="true";p.TurnSni=Scalar(d,"turn_sni");p.AutoCalls=Scalar(d,"hash_source")=="auto";if(d.ContainsKey("vk_call_count"))p.CallCount=Int32.Parse(Scalar(d,"vk_call_count"));if(d.ContainsKey("workers_override"))p.Workers=Int32.Parse(Scalar(d,"workers_override"));
    string host=Scalar(d,"server"),port=Scalar(d,"server_port",kind=="csqtt"?"46000":"56000"),password=Scalar(d,"password"),calls=Scalar(d,"hashes"),name=Scalar(d,"name",kind.ToUpperInvariant());if(name.Length>256||String.IsNullOrWhiteSpace(name)||name.Any(Char.IsControl))throw new FormatException("Некорректное название профиля.");
    string link;if(kind=="qwdtt"){string mode=Scalar(d,"mode","wg");p.QwdttMode=mode=="raw"||mode=="rawtun"?"raw":new[]{"wg","wireguard","vpn","socks"}.Contains(mode)?"wireguard":null;if(p.QwdttMode==null)throw new FormatException("Некорректный режим QWDTT.");link=QwdttProfile.Link(name,(host.Contains(":")?"["+host+"]":host)+":"+port,password,calls)+"&mode="+p.QwdttMode;}else{link=kind+"://connect?v="+(kind=="csqtt"?"2":"1")+"&host="+Uri.EscapeDataString(host)+"&"+(kind=="csqtt"?"peer":"dtls")+"="+port+"&password="+Uri.EscapeDataString(password);if(calls.Length>0)link+="&hashes="+String.Join(",",Calls(calls).Select(Uri.EscapeDataString));if(kind=="wdtt")link+="&wg="+Scalar(d,"wg_port","56001")+"&local="+Scalar(d,"local_port","9000");link+="&name="+Uri.EscapeDataString(name);}
    string exact=Scalar(d,"link_workers","0"),workers=exact!="0"?exact:Scalar(d,"workers");if(workers.Length>0)link+="&workers="+workers;
    var n=Links.Read(link).Single();if(kind=="csqtt"){string g=Scalar(d,"csqtt_generation");n.CsqttGeneration=g=="legacy"?"2.1.9":g.Length==0?null:CsqttGenerations.Normalize(g);}n.Name=name;p.Options["hashes"]=calls;n.TurnPreferences=p;Validate(n,p);result.Add(n);
   }return result;
  }
 }
}
